const stationsByCode = new Map<string, Station>(stations.map((station) => [station.code, station]));

/**
 * Codes that anchor the national map view. Rendering all 1091 stations at once
 * produces an unreadable smear of markers, so map surfaces draw this subset
 * plus whatever stations the trains actually on screen are calling at.
 */
export const MAJOR_STATION_CODES: readonly string[] = ["ADI","ADRA","AGC","AII","ANVT","ASN","ASR","BAM","BAY","BBS","BE","BINA","BJU","BKN","BKSC","BL","BNC","BPL","BPQ","BRC","BSB","BSL","BSP","BVI","BWN","BZA","CAN","CBE","CDG","CKP","CLT","CNB","CSMT","CTC","DD","DDU","DEE","DHN","DLI","DNR","DR","DURG","DWR","ED","ERS","ET","G","GAYA","GDR","GHY","GKP","GNT","GTL","GWL","HWH","HYB","JAM","JAT","JBP","JP","JSG","JU","JUC","KCG","KGP","KIR","KJM","KOAA","KOP","KOTA","KTE","KTYM","KUR","KYN","KZJ","LDH","LKO","LTT","MAO","MAS","MB","MDU","MFP","MLDT","MMCT","MMR","MRJ","MS","MTJ","MYS","NDLS","NED","NGP","NJP","NLR","NZM","PGT","PNBE","PNVL","PRYJ","PTK","PUNE","PURI","QLN","R","RJT","RJY","RKMP","RNC","ROU","RU","RXL","SA","SBC","SC","SDAH","SHM","SPJ","SRC","ST","STA","SUR","SVDK","TATA","TBM","TCR","TNA","TPJ","TPTY","TVC","UBL","UDZ","UMB","VAPI","VSKP","VZM","WL","YPR"];

export const majorStations: Station[] = MAJOR_STATION_CODES
  .map((code) => stationsByCode.get(code))
  .filter((station): station is Station => Boolean(station));

export function getStationByCode(code: string): Station | undefined {
  if (!code) return undefined;
  return stationsByCode.get(code.trim().toUpperCase());
}

export function searchStations(query: string): Station[] {
  const q = query.trim().toLowerCase();
  if (!q) return [];
  return stations.filter(
    (station) => station.name.toLowerCase().includes(q) || station.code.toLowerCase().includes(q),
  );
}

/**
 * Stations lying between two codes on a corridor is a routing question, not a
 * geometry one — it depends on which line a given train takes. The real answer
 * comes from that train's published route (`trainService.getRouteProgress`),
 * so this only resolves the two endpoints it can actually vouch for.
 */
export function getStationsBetween(origin: string, destination: string): Station[] {
  const originStation = getStationByCode(origin);
  const destinationStation = getStationByCode(destination);
  if (!originStation || !destinationStation) return [];
  return [originStation, destinationStation];
}
